import hmac
import hashlib
import json
import time
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SECRET_KEY = os.urandom(32)
REFRESH_SECRET = os.urandom(32)

# Rate limiting store
rate_limits = {}

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def create_token(payload, secret=SECRET_KEY, algorithm='HS256'):
    """Create a signed token with header.payload.signature format."""
    header = {'alg': algorithm, 'typ': 'JWT'}
    h = base64url_encode(json.dumps(header))
    p = base64url_encode(json.dumps(payload))
    signing_input = f"{h}.{p}"
    sig = compute_signature(signing_input, secret, algorithm)
    return f"{h}.{p}.{sig}"

def base64url_encode(data):
    import base64
    if isinstance(data, str):
        data = data.encode()
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

def base64url_decode(data):
    import base64
    if isinstance(data, str):
        data = data.encode()
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

def compute_signature(signing_input, secret, algorithm):
    """Compute HMAC signature for the given algorithm."""
    if algorithm == 'HS256':
        key = secret if isinstance(secret, bytes) else secret.encode()
        sig = hmac.new(key, signing_input.encode(), hashlib.sha256).digest()
        return base64url_encode(sig)
    elif algorithm == 'HS384':
        key = secret if isinstance(secret, bytes) else secret.encode()
        sig = hmac.new(key, signing_input.encode(), hashlib.sha384).digest()
        return base64url_encode(sig)
    else:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

def verify_token(token, secret=SECRET_KEY):
    """Verify token signature and return payload if valid."""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None

        header_b64, payload_b64, signature_b64 = parts

        # Decode and validate header
        header = json.loads(base64url_decode(header_b64))
        algorithm = header.get('alg', 'HS256')

        # Security: only allow HMAC algorithms
        allowed_algorithms = ['HS256', 'HS384']
        if algorithm not in allowed_algorithms:
            return None

        # Verify signature
        signing_input = f"{header_b64}.{payload_b64}"
        expected_sig = compute_signature(signing_input, secret, algorithm)

        if not constant_time_compare(signature_b64, expected_sig):
            return None

        # Decode payload
        payload = json.loads(base64url_decode(payload_b64))

        # Check expiration
        if 'exp' in payload and payload['exp'] < time.time():
            return None

        return payload
    except Exception:
        return None

def create_refresh_token(user_id):
    """Create a long-lived refresh token."""
    payload = {
        'sub': user_id,
        'type': 'refresh',
        'exp': time.time() + 86400 * 30,  # 30 days
        'iat': time.time()
    }
    return create_token(payload, REFRESH_SECRET, 'HS256')

def verify_refresh_token(token):
    """Verify a refresh token and return new access token."""
    payload = verify_token(token, REFRESH_SECRET)
    if payload and payload.get('type') == 'refresh':
        # Issue new access token
        new_payload = {
            'sub': payload['sub'],
            'type': 'access',
            'exp': time.time() + 3600,
            'iat': time.time()
        }
        return create_token(new_payload, SECRET_KEY, 'HS256')
    return None

