def verify_password(username, password):
    """Verify password using PBKDF2."""
    user = users_db.get(username)
    if not user:
        # Constant-time: still compute hash to prevent user enumeration
        hashlib.pbkdf2_hmac('sha256', password.encode(), b'dummy_salt_value', 100000)
        return False

    expected = user['password_hash']
    salt = user['salt'].encode()
    computed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
    return constant_time_compare(computed, expected)

def check_rate_limit(client_ip, endpoint, max_requests=10, window=60):
    """Rate limiting per IP per endpoint."""
    key = f"{client_ip}:{endpoint}"
    now = time.time()

    if key not in rate_limits:
        rate_limits[key] = []

    # Clean old entries
    rate_limits[key] = [t for t in rate_limits[key] if now - t < window]

    if len(rate_limits[key]) >= max_requests:
        return False

    rate_limits[key].append(now)
    return True

def sanitize_input(value, max_length=200):
    """Sanitize user input - strip dangerous characters."""
    if not isinstance(value, str):
        return ''
    value = value[:max_length]
    # Remove null bytes and control characters
    value = re.sub(r'[\x00-\x1f\x7f]', '', value)
    return value

def get_user_data(username, requesting_user_role):
    """Get user data with role-based access control."""
    user = users_db.get(username)
    if not user:
        return {'error': 'User not found'}

    # Base data everyone can see
    result = {'username': username, 'role': user['role'], 'active': user['active']}

    # Admin can see additional fields
    if requesting_user_role == 'admin':
        result['salt'] = user['salt']

    return result

class TokenRefreshHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))

        if content_length > 4096:
            self.send_error(413)
            return

        body = self.rfile.read(content_length)

        client_ip = self.client_address[0]

        if path == '/auth/login':
            if not check_rate_limit(client_ip, '/auth/login', max_requests=5, window=300):
                self.send_json(429, {'error': 'Rate limited'})
                return

            try:
                data = json.loads(body)
                username = sanitize_input(data.get('username', ''))
                password = data.get('password', '')

                if not username or not password:
                    self.send_json(401, {'error': 'Invalid credentials'})
                    return

                if not verify_password(username, password):
                    self.send_json(401, {'error': 'Invalid credentials'})
                    return

                user = users_db[username]
                if not user['active']:
                    self.send_json(403, {'error': 'Account disabled'})
                    return

                access_token = create_token(
                    {'sub': username, 'role': user['role'], 'type': 'access',
                     'exp': time.time() + 3600, 'iat': time.time()},
                    SECRET_KEY, 'HS256'
                )
                refresh_token = create_refresh_token(username)

                self.send_json(200, {
                    'access_token': access_token,
                    'refresh_token': refresh_token,
                    'expires_in': 3600
                })
            except (json.JSONDecodeError, KeyError):
                self.send_json(400, {'error': 'Invalid request'})

        elif path == '/auth/refresh':
            if not check_rate_limit(client_ip, '/auth/refresh', max_requests=20, window=60):
                self.send_json(429, {'error': 'Rate limited'})
                return

            try:
                data = json.loads(body)
                refresh_token = data.get('refresh_token', '')

                if not refresh_token:
                    self.send_json(400, {'error': 'Missing refresh token'})
                    return

                new_access = verify_refresh_token(refresh_token)
                if new_access:
                    self.send_json(200, {'access_token': new_access, 'expires_in': 3600})
                else:
                    self.send_json(401, {'error': 'Invalid refresh token'})
            except json.JSONDecodeError:
                self.send_json(400, {'error': 'Invalid request'})

        elif path == '/auth/revoke':
            # Token revocation - verify the access token first
            auth_header = self.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                self.send_json(401, {'error': 'Missing authorization'})
                return

            token = auth_header[7:]
            payload = verify_token(token)
            if not payload:
                self.send_json(401, {'error': 'Invalid token'})
                return

            # In production, add refresh token to blacklist
            self.send_json(200, {'message': 'Token revoked'})

        else:
            self.send_error(404)

    def do_GET(self):
        path = urlparse(self.path).path
        params = parse_qs(urlparse(self.path).query)
        client_ip = self.client_address[0]

        if path == '/api/user':
            if not check_rate_limit(client_ip, '/api/user'):
                self.send_json(429, {'error': 'Rate limited'})
                return

            auth_header = self.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                self.send_json(401, {'error': 'Missing authorization'})
                return

            token = auth_header[7:]
            payload = verify_token(token)
            if not payload or payload.get('type') != 'access':
                self.send_json(401, {'error': 'Invalid token'})
                return

            target_user = sanitize_input(params.get('username', [payload['sub']])[0])
            user_data = get_user_data(target_user, payload.get('role', 'user'))
            self.send_json(200, user_data)

        else:
            self.send_error(404)

    def send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def log_message(self, format, *args):
        pass  # Suppress default logging

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), TokenRefreshHandler)
    server.serve_forever()
